@layer hj.components {
  /* Customise: --hj-banner-radius · --hj-banner-padding */
  .hj-banner {
    --_fill: color-mix(in srgb, var(--hj-fg) 5%, var(--hj-surface));
    --_ink: var(--hj-fg-dim);
    --_ring: var(--hj-line);
    display: grid;
    grid-template-rows: 1fr;
    font-family: var(--hj-font-sans);
    /* the dismissal: fade first (fast), then the rows close up — the one layout transition */
    transition:
      opacity var(--hj-dur-fast) var(--hj-ease-out),
      transform var(--hj-dur-fast) var(--hj-ease-out),
      grid-template-rows var(--hj-dur-base) var(--hj-ease-out),
      margin var(--hj-dur-base) var(--hj-ease-out);
  }
  .hj-banner[data-tone='info'] {
    --_fill: var(--hj-info-soft);
    --_ink: var(--hj-info);
    --_ring: color-mix(in srgb, var(--hj-info) 22%, transparent);
  }
  .hj-banner[data-tone='success'] {
    --_fill: var(--hj-success-soft);
    --_ink: var(--hj-success);
    --_ring: color-mix(in srgb, var(--hj-success) 22%, transparent);
  }
  .hj-banner[data-tone='warning'] {
    --_fill: var(--hj-warning-soft);
    --_ink: var(--hj-warning);
    --_ring: color-mix(in srgb, var(--hj-warning) 26%, transparent);
  }
  .hj-banner[data-tone='danger'] {
    --_fill: var(--hj-danger-soft);
    --_ink: var(--hj-danger);
    --_ring: color-mix(in srgb, var(--hj-danger) 22%, transparent);
  }
  .hj-banner[data-ending-style] {
    opacity: 0;
    transform: translateY(calc(-4px * var(--hj-travel)));
  }
  .hj-banner[data-collapsing] {
    grid-template-rows: 0fr;
  }

  .hj-banner-inner {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    min-height: 0;
    overflow: hidden;
    padding: var(--hj-banner-padding, 14px 14px 14px 16px);
    border-radius: var(--hj-banner-radius, var(--hj-radius-md));
    background: var(--_fill);
    box-shadow: inset 0 0 0 1px var(--_ring);
    color: var(--hj-fg);
  }
  .hj-banner[data-collapsing] .hj-banner-inner {
    padding-block: 0;
  }
  .hj-banner-glyph {
    display: inline-flex;
    flex: none;
    margin-top: 1px;
    color: var(--_ink);
    line-height: 0;
  }
  .hj-banner-glyph > svg {
    width: 20px;
    height: 20px;
  }
  .hj-banner-content {
    display: flex;
    flex: 1;
    flex-direction: column;
    gap: 2px;
    min-width: 0;
  }
  .hj-banner-title {
    margin: 0;
    font-size: 14.5px;
    font-weight: 600;
    line-height: 1.35;
  }
  .hj-banner-description {
    margin: 0;
    font-size: 13.5px;
    line-height: 1.5;
    color: var(--hj-fg-dim);
  }
  .hj-banner-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-top: 10px;
  }

  .hj-banner-dismiss {
    position: relative;
    flex: none;
    display: grid;
    place-items: center;
    width: 28px;
    height: 28px;
    margin: -4px -4px 0 0;
    padding: 0;
    border: 0;
    border-radius: var(--hj-radius-pill);
    background: transparent;
    color: var(--hj-fg-mute);
    line-height: 0;
    cursor: pointer;
    transition:
      background-color var(--hj-dur-fast) var(--hj-ease-out),
      color var(--hj-dur-fast) var(--hj-ease-out);
  }
  .hj-banner-dismiss::before {
    content: '';
    position: absolute;
    inset: -8px;
  }
  .hj-banner-dismiss:hover {
    background: color-mix(in srgb, var(--hj-fg) 8%, transparent);
    color: var(--hj-fg);
  }
  .hj-banner-dismiss > svg {
    width: 14px;
    height: 14px;
  }
}

'use client';
import { useRender } from '@base-ui/react/use-render';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { prefersReducedMotion } from '../../system/motion.ts';
import { elementPart } from '../../system/part.tsx';
import type { ElementPartProps } from '../../system/part.tsx';
import { cls, withDefaults } from '../../system/slot.ts';

export type Tone = 'neutral' | 'info' | 'success' | 'warning' | 'danger';

interface BannerState {
  dismiss: () => void;
}
const BannerContext = React.createContext<BannerState>({ dismiss: () => {} });

/** Exit timing: fade out (fast), then the rows close up (base). */
const FADE_MS = 180;
const COLLAPSE_MS = 260;

export interface RootOwnProps {
  /** Glyph and tint. Status is always word + glyph + tint, never colour alone. @default 'neutral' */
  tone?: Tone;
  /** Lead with the tone's glyph. @default true */
  icon?: boolean;
  /** Controlled visibility. */
  open?: boolean;
  /** Uncontrolled initial visibility. @default true */
  defaultOpen?: boolean;
  /** Called when Banner.Dismiss is pressed (after the exit has finished). */
  onOpenChange?: (open: boolean) => void;
}
export interface RootProps extends RootOwnProps, Omit<React.ComponentProps<'div'>, 'className'> {
  className?: string;
  render?: useRender.RenderProp;
}

/**
 * An inline notice that stays until it is resolved or dismissed: a sync problem, a plan limit,
 * an update. Danger and warning are announced as alerts; the rest as status.
 */
export function Root(props: RootProps): React.ReactElement | null {
  const config = useHanjiConfig();
  const {
    tone = 'neutral',
    icon = true,
    open: openProp,
    defaultOpen = true,
    onOpenChange,
    render,
    className,
    children,
    ...rest
  } = withDefaults(config, 'Banner.Root', props);
  const [openState, setOpenState] = React.useState(defaultOpen);
  const open = openProp ?? openState;
  const [phase, setPhase] = React.useState<'idle' | 'leaving' | 'collapsing'>('idle');
  const ref = React.useRef<HTMLDivElement>(null);
  const onOpenChangeRef = React.useRef(onOpenChange);
  React.useLayoutEffect(() => {
    onOpenChangeRef.current = onOpenChange;
  });

  // created once: it reads the latest onOpenChange through a ref, so it never goes stale
  const [dismiss] = React.useState(() => (): void => {
    // honours the nearest data-hj-motion, then the system setting
    const reduced = prefersReducedMotion(ref.current);
    setPhase('leaving');
    window.setTimeout(
      () => {
        setPhase('collapsing');
        window.setTimeout(
          () => {
            setPhase('idle');
            setOpenState(false);
            onOpenChangeRef.current?.(false);
          },
          reduced ? 0 : COLLAPSE_MS,
        );
      },
      reduced ? 120 : FADE_MS,
    );
  });
  const ctx = React.useMemo(() => ({ dismiss }), [dismiss]);

  const urgent = tone === 'danger' || tone === 'warning';
  const glyph =
    tone === 'success'
      ? config.icons.checkCircle
      : tone === 'danger'
        ? config.icons.xCircle
        : tone === 'warning'
          ? config.icons.alert
          : config.icons.info;

  const element = useRender({
    render,
    ref,
    defaultTagName: 'div',
    props: {
      role: urgent ? 'alert' : 'status',
      ...rest,
      'data-tone': tone,
      'data-ending-style': phase === 'idle' ? undefined : '',
      'data-collapsing': phase === 'collapsing' ? '' : undefined,
      className: cls(config, 'Banner.Root', 'hj-banner', className) as string | undefined,
      children: (
        <div className={config.unstyled ? undefined : 'hj-banner-inner'}>
          {icon ? (
            <span className={config.unstyled ? undefined : 'hj-banner-glyph'} aria-hidden="true">
              {glyph}
            </span>
          ) : null}
          {children}
        </div>
      ),
    },
  });
  if (!open) return null;
  return <BannerContext.Provider value={ctx}>{element}</BannerContext.Provider>;
}

/** Holds the title and the sentence. */
export const Content: (props: ElementPartProps<'div'>) => React.ReactElement = elementPart(
  'div',
  'Banner.Content',
  'hj-banner-content',
);
export const Title: (props: ElementPartProps<'p'>) => React.ReactElement = elementPart(
  'p',
  'Banner.Title',
  'hj-banner-title',
);
export const Description: (props: ElementPartProps<'p'>) => React.ReactElement = elementPart(
  'p',
  'Banner.Description',
  'hj-banner-description',
);
/** One or two actions (render Buttons inside). */
export const Actions: (props: ElementPartProps<'div'>) => React.ReactElement = elementPart(
  'div',
  'Banner.Actions',
  'hj-banner-actions',
);

export interface DismissProps extends Omit<React.ComponentProps<'button'>, 'className'> {
  className?: string;
}

/** The ✕. Fades the banner out, then closes the space it held. */
export function Dismiss(props: DismissProps): React.ReactElement {
  const config = useHanjiConfig();
  const { dismiss } = React.useContext(BannerContext);
  const { className, onClick, children, ...rest } = withDefaults(config, 'Banner.Dismiss', props);
  return (
    <button
      type="button"
      aria-label={children ? undefined : config.strings.dismiss}
      {...rest}
      onClick={(e) => {
        onClick?.(e);
        if (!e.defaultPrevented) dismiss();
      }}
      className={
        cls(config, 'Banner.Dismiss', 'hj-banner-dismiss', className) as string | undefined
      }
    >
      {children ?? config.icons.x}
    </button>
  );
}

export * as Banner from './banner.tsx';
export type {
  DismissProps as BannerDismissProps,
  RootOwnProps as BannerRootOwnProps,
  RootProps as BannerRootProps,
  Tone as BannerTone,
} from './banner.tsx';
